import math

def prime_fib(n: int):
    """
    Returns the n-th Fibonacci number that is also prime.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(math.isqrt(num)) + 1, 2):
            if num % i == 0:
                return False
        return True

    count = 0
    a, b = 0, 1  # Initial Fibonacci numbers
    while True:
        # Next Fibonacci number
        a, b = b, a + b
        if is_prime(b):
            count += 1
            if count == n:
                return b

