def compare_one(a, b):
    """
    Compare two values (int, float, or string representing a real number) and
    return the larger one in its original type. Return None if they are equal.

    Rules for strings:
    - Strings that represent numbers may use a comma as the decimal separator (e.g., "2,3").
    - The function should try to convert such strings to float for comparison,
      but return the original string when it is the larger value.
    """
    # Helper to safely try converting string to float, using comma as decimal if needed
    def to_num(x):
        try:
            if isinstance(x, str):
                # Handle comma as decimal separator (common in some locales)
                x_clean = x.replace(',', '.')
                return float(x_clean)
            return float(x)
        except ValueError:
            # If it's not a valid number string, treat as lowest possible (for comparison)
            return float('-inf')

    num_a = to_num(a)
    num_b = to_num(b)

    # Compare after conversion
    if num_a > num_b:
        # If a was originally a string, return the original string
        return a if isinstance(a, str) else a
    elif num_b > num_a:
        # If b was originally a string, return the original string
        return b if isinstance(b, str) else b
    else:
        return None
