import math

def words_in_sentence(sentence: str) -> str:
    """
    Returns a string consisting of words from the input sentence whose lengths are prime numbers,
    preserving the original order. Words are separated by whitespace in the input.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.isqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Split the sentence into words (split() automatically handles any whitespace)
    words = sentence.split()
    # Filter words with prime lengths and join them with a space
    prime_length_words = [word for word in words if is_prime(len(word))]
    return " ".join(prime_length_words)
